<script setup>
import {ref,onMounted} from 'vue';import {api} from '../lib/api';import StateBox from '../components/StateBox.vue';
const rows=ref([]),loading=ref(true),error=ref(''),search=ref(''),page=ref(1),total=ref(0);async function load(){loading.value=true;error.value='';try{const r=await api.get('/players',{params:{search:search.value,page:page.value}});rows.value=r.data;total.value=r.meta.total;}catch(e){error.value=e.message;}finally{loading.value=false;}}onMounted(load);
</script><template><div class="heading"><div><p class="eyebrow">BASE DE DATOS LOCAL</p><h1>Jugadores</h1><p class="sub">Jugadores publicados al menos una vez.</p></div><span class="metric">{{total}} jugadores</span></div><div class="toolbar"><input v-model="search" @keyup.enter="page=1;load()" placeholder="Buscar jugador…"/><button class="btn" @click="page=1;load()">Buscar</button></div><StateBox :loading="loading" :error="error" :empty="!rows.length"/><div class="cards" v-if="!loading&&!error"><RouterLink class="competition-card" v-for="p in rows" :key="p.id" :to="'/players/'+p.id"><span class="glyph">♙</span><span><strong>{{p.name}}</strong><small>{{p.nationality||'Nacionalidad no disponible'}}</small></span><span class="arrow">→</span></RouterLink></div><div class="pager" v-if="total>20"><button class="btn muted" :disabled="page<=1" @click="page--;load()">Anterior</button><span>{{page}}</span><button class="btn muted" :disabled="page*20>=total" @click="page++;load()">Siguiente</button></div></template>
